pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address target, uint256 value, bytes memory data) public {
        // Ensure the owner can call sendMoney
        vm.assume(target != address(0));
        // Make first deposit via sendMoney (value > 0 triggers receive)
        vm.deal(address(this), 1 ether);
        vm.prank(c.owner());
        (bool success1, ) = address(c).call{value: 1 ether}("");
        // Now make second sendMoney call
        vm.deal(address(this), value);
        vm.prank(c.owner());
        (bool success2, ) = address(c).call{value: value}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        // Rule: after two deposits, depositsCount must be 2 if second sendMoney succeeded, else remains 1 if it reverted
        uint256 count = c.depositsCount();
        // The reference: after first deposit, depositsCount=1; second sendMoney always succeeds (no revert on receive) -> count=2
        // The mutant: second sendMoney will revert because receive requires depositsCount==0 (false) -> count=1
        assertTrue(success2 ? count == 2 : count == 1);
    }
}

