        // Bound withdrawAmount to a reasonable value (e.g., within contract balance after sendMoney)
        // Deployer (owner) starts with some ether for gas
        vm.deal(address(this), 10 ether);
        // Fund the contract
        payable(address(c)).transfer(1 ether);

        // Record owner's balance before sendMoney
        address owner = c.owner();
        uint256 ownerBalanceBefore = owner.balance;

        // Execute sendMoney
        (bool success, ) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", target, value, data));
        // We don't care if sendMoney succeeds or reverts

        // After sendMoney, owner's balance should not have changed because withdraw sends 0
        // Assert that owner's balance is unchanged
        assertTrue(owner.balance == ownerBalanceBefore);
    }
}

